function main(c) {
  var out = {};
  for (var k in c.base) { out[k] = c.base[k]; }
  for (var i = 0; i < c.fields.length; i++) {
    var f = c.fields[i];
    if (f.kind === 'both') { return { defer: true }; }
    var key = f.path.slice(1);
    var side = f.kind === 'remote' ? 'remote' : 'local';
    if (f.present[side]) { out[key] = f[side]; } else { delete out[key]; }
  }
  return { doc: out };
}
